import { createClient } from 'npm:@supabase/supabase-js@2.117.3';

/*__BUNDLE__*/

const CORS = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'GET, HEAD, OPTIONS' };

function secretKey() {
  try {
    const keys = JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS') ?? '{}');
    const first = keys.default ?? Object.values(keys)[0];
    if (first) return String(first);
  } catch { /* fall back to the legacy key */ }
  return Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS });
  if (req.method !== 'GET' && req.method !== 'HEAD') return new Response(JSON.stringify({ error: 'method' }), { status: 405, headers: { ...CORS, 'Content-Type': 'application/json' } });
  let db = null;
  try { db = createClient(Deno.env.get('SUPABASE_URL'), secretKey(), { auth: { persistSession: false, autoRefreshToken: false } }); } catch { /* reported as down below */ }
  const r = await checkHealth({
    now: () => new Date(),
    ping: () => (db ? db.from('app_migrations').select('version').limit(1) : Promise.reject(new Error('no client'))),
  });
  return new Response(req.method === 'HEAD' ? null : JSON.stringify(r.body), { status: r.status, headers: { ...CORS, 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
});
